use bench_sandbox::b64encode;
#[test] fn empty() { assert_eq!(b64encode(b""), ""); }
#[test] fn f() { assert_eq!(b64encode(b"f"), "Zg=="); }
#[test] fn fo() { assert_eq!(b64encode(b"fo"), "Zm8="); }
#[test] fn foo() { assert_eq!(b64encode(b"foo"), "Zm9v"); }
#[test] fn foob() { assert_eq!(b64encode(b"foob"), "Zm9vYg=="); }
#[test] fn fooba() { assert_eq!(b64encode(b"fooba"), "Zm9vYmE="); }
#[test] fn foobar() { assert_eq!(b64encode(b"foobar"), "Zm9vYmFy"); }
